def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Periodic copies of a small motif: recolor blank cells in later copies
    # only where the first copy has foreground.
    for start in range(1, h-3, 10):
        for dr in range(4):
            rr = start + dr
            if rr >= h: continue
            for c in range(w):
                if grid[dr][c] != bg and grid[rr][c] == bg:
                    out[rr][c] = 1
    # A bar's trailing background is the anomalous continuation relative to
    # another complete bar of the same color.
    fullbar = any(all(v == row[0] for v in row) and row[0] != bg for row in grid)
    for r, row in enumerate(grid):
        if not fullbar or not row or row[0] == bg: continue
        color = row[0]
        end = 0
        while end < w and row[end] == color: end += 1
        if end < w and row[end] == bg and any(all(v == color for v in other) for other in grid):
            for c in range(end, w):
                if row[c] == bg: out[r][c] = 1
    return out

